// --- CONFIGURACIÓN EMAILJS: reemplazar con valores reales del cliente ---
var EMAILJS_PUBLIC_KEY   = 'TU_PUBLIC_KEY_AQUI';
var EMAILJS_SERVICE_ID   = 'TU_SERVICE_ID_AQUI';
var EMAILJS_TEMPLATE_ID  = 'TU_TEMPLATE_ID_AQUI';

emailjs.init(EMAILJS_PUBLIC_KEY);

function initStickyHeader() {
  var header = document.getElementById('site-header');
  if (!header) return;

  function onScroll() {
    if (window.scrollY > 50) {
      header.classList.add('is-scrolled');
    } else {
      header.classList.remove('is-scrolled');
    }
  }

  window.addEventListener('scroll', onScroll);
  onScroll();
}

function initMobileMenu() {
  var navToggle = document.getElementById('nav-toggle');
  var navMenu   = document.getElementById('nav-menu');
  var navMain   = document.getElementById('nav-main');

  if (!navToggle || !navMenu) return;

  navToggle.addEventListener('click', function () {
    navMain.classList.toggle('is-open');
    var isOpen = navMain.classList.contains('is-open');
    navToggle.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
  });

  var navLinks = navMenu.querySelectorAll('.nav__link');
  navLinks.forEach(function (link) {
    link.addEventListener('click', function () {
      navMain.classList.remove('is-open');
      navToggle.setAttribute('aria-expanded', 'false');
    });
  });
}

function initActiveNavOnScroll() {
  var sectionIds = ['section-home', 'section-services', 'section-about', 'section-contact'];

  var sections = sectionIds.map(function (id) {
    return document.getElementById(id);
  }).filter(function (el) {
    return el !== null;
  });

  var navLinks = document.querySelectorAll('#nav-menu .nav__link');

  window.addEventListener('scroll', function () {
    var activeSection = null;

    sections.forEach(function (section) {
      var rect = section.getBoundingClientRect();
      if (rect.top <= window.innerHeight / 2 && rect.top > -section.offsetHeight) {
        activeSection = section;
      }
    });

    if (!activeSection) return;

    navLinks.forEach(function (link) {
      link.classList.remove('is-active');
    });

    navLinks.forEach(function (link) {
      if (link.getAttribute('href') === '#' + activeSection.id) {
        link.classList.add('is-active');
      }
    });
  });
}

function initScrollAnimations() {
  var elements = document.querySelectorAll('.animate-on-scroll');
  if (!elements.length) return;

  var observer = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (entry.isIntersecting) {
        entry.target.classList.add('is-active');
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.15 });

  elements.forEach(function (el) {
    observer.observe(el);
  });
}

function validateForm(formData) {
  var isValid = true;

  var nameInput    = document.getElementById('form-name');
  var emailInput   = document.getElementById('form-email');
  var messageInput = document.getElementById('form-message');
  var nameError    = document.getElementById('form-name-error');
  var emailError   = document.getElementById('form-email-error');
  var messageError = document.getElementById('form-message-error');

  nameInput.classList.remove('has-error');
  emailInput.classList.remove('has-error');
  messageInput.classList.remove('has-error');
  nameError.classList.add('is-hidden');
  emailError.classList.add('is-hidden');
  messageError.classList.add('is-hidden');

  if (formData.name.trim().length === 0) {
    nameInput.classList.add('has-error');
    nameError.classList.remove('is-hidden');
    isValid = false;
  }

  var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(formData.email.trim())) {
    emailInput.classList.add('has-error');
    emailError.classList.remove('is-hidden');
    isValid = false;
  }

  if (formData.message.trim().length === 0) {
    messageInput.classList.add('has-error');
    messageError.classList.remove('is-hidden');
    isValid = false;
  }

  return isValid;
}

function initContactForm() {
  var form       = document.getElementById('contact-form');
  var submitBtn  = document.getElementById('form-submit');
  var feedback   = document.getElementById('form-feedback');

  if (!form) return;

  form.addEventListener('submit', function (e) {
    e.preventDefault();

    var honeypot = form.querySelector('[name="website"]');
    if (honeypot && honeypot.value.trim() !== '') return;

    var formData = {
      name:    document.getElementById('form-name').value,
      email:   document.getElementById('form-email').value,
      message: document.getElementById('form-message').value
    };

    if (!validateForm(formData)) return;

    submitBtn.disabled = true;
    submitBtn.classList.add('is-hidden');
    feedback.classList.remove('feedback--success');
    feedback.classList.remove('feedback--error');
    feedback.classList.add('is-hidden');

    var templateParams = {
      from_name:    formData.name.trim(),
      from_email:   formData.email.trim(),
      message:      formData.message.trim()
    };

    emailjs.send(EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, templateParams)
      .then(function () {
        feedback.textContent = '¡Mensaje enviado con éxito! Nos pondremos en contacto pronto.';
        feedback.classList.remove('feedback--error');
        feedback.classList.add('feedback--success');
        feedback.classList.remove('is-hidden');
        form.reset();
        submitBtn.disabled = false;
        submitBtn.classList.remove('is-hidden');
      })
      .catch(function () {
        feedback.textContent = 'Ocurrió un error al enviar el mensaje. Por favor, inténtalo de nuevo.';
        feedback.classList.remove('feedback--success');
        feedback.classList.add('feedback--error');
        feedback.classList.remove('is-hidden');
        submitBtn.disabled = false;
        submitBtn.classList.remove('is-hidden');
      });
  });
}

document.addEventListener('DOMContentLoaded', function () {
  initStickyHeader();
  initMobileMenu();
  initActiveNavOnScroll();
  initScrollAnimations();
  initContactForm();
});

/* ============================================================
   PRODUCTORA 2 — style.css
   Hoja de estilos única y plana. Sin @import de archivos locales.
   ============================================================ */

/* ============================================================
   1. TOKENS DE DISEÑO — Custom Properties
   ============================================================ */
:root {
  /* Paleta */
  --color-bg-dark: #0a0a0a;
  --color-bg-section: #111111;
  --color-bg-card: #1a1a1a;
  --color-accent: #c9a84c;
  --color-accent-hover: #e0bc6a;
  --color-text-primary: #f0f0f0;
  --color-text-secondary: #a0a0a0;
  --color-text-on-accent: #0a0a0a;
  --color-border: #2a2a2a;
  --color-error: #e05252;
  --color-success: #52a052;

  /* Tipografía */
  --font-display: 'Playfair Display', Georgia, serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --font-size-base: 1rem;
  --font-size-sm: 0.875rem;
  --font-size-lg: 1.25rem;
  --font-size-xl: 1.5rem;
  --font-size-2xl: 2rem;
  --font-size-3xl: 2.75rem;
  --font-size-4xl: 3.75rem;

  /* Espaciado */
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 1.5rem;
  --space-lg: 2.5rem;
  --space-xl: 4rem;
  --space-2xl: 6rem;

  /* Layout */
  --container-max: 1200px;
  --header-height: 72px;

  /* Efectos */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --transition-fast: 150ms ease;
  --transition-base: 300ms ease;
  --shadow-card: 0 4px 24px rgba(0, 0, 0, 0.4);
  --shadow-header: 0 2px 16px rgba(0, 0, 0, 0.6);
}

/* ============================================================
   2. RESET Y BASE GLOBAL
   ============================================================ */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-body);
  background-color: var(--color-bg-dark);
  color: var(--color-text-primary);
  line-height: 1.6;
  overflow-x: hidden;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

a {
  color: inherit;
  text-decoration: none;
}

ul,
ol {
  list-style: none;
}

/* ============================================================
   3. CLASES DE ESTADO DEL CONTRATO
   Exactamente cuatro. Sin excepciones.
   ============================================================ */

/* Oculta el elemento del flujo visual. Única excepción de !important. */
.is-hidden {
  display: none !important;
}

/*
  .is-active  — Reservada. Estilos visuales definidos por componente.
  .is-open    — Reservada. Estilos visuales definidos por componente.
  .has-error  — Reservada. Estilos visuales definidos por componente.
*/

/* ============================================================
   4. LAYOUT: CONTENEDOR Y SECCIONES
   ============================================================ */
.section {
  padding: var(--space-2xl) var(--space-sm);
  scroll-margin-top: var(--header-height);
}

.section__container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--space-md);
}

.section__header {
  text-align: center;
  margin-bottom: var(--space-xl);
}

.section__header--left {
  text-align: left;
}

.section__title {
  font-family: var(--font-display);
  font-size: var(--font-size-3xl);
  color: var(--color-text-primary);
  line-height: 1.2;
  margin-bottom: var(--space-sm);
}

.section__title--sm {
  font-size: var(--font-size-xl);
}

.section__subtitle {
  font-size: var(--font-size-lg);
  color: var(--color-text-secondary);
  max-width: 600px;
  margin: 0 auto;
}

.section--services,
.section--about {
  background-color: var(--color-bg-section);
}

/* ============================================================
   5. HEADER Y NAVEGACIÓN
   ============================================================ */
#site-header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: var(--header-height);
  z-index: 1000;
  background-color: transparent;
  transition: background-color var(--transition-base),
              box-shadow var(--transition-base);
}

#site-header.is-scrolled {
  background-color: rgba(10, 10, 10, 0.95);
  backdrop-filter: blur(8px);
  box-shadow: var(--shadow-header);
}

.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--space-md);
}

.header__logo {
  font-family: var(--font-display);
  font-size: var(--font-size-xl);
  font-weight: 700;
  color: var(--color-accent);
  letter-spacing: 0.02em;
}

#nav-menu {
  display: flex;
  gap: var(--space-lg);
  align-items: center;
}

.nav__link {
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text-secondary);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: var(--space-xs) 0;
  position: relative;
  transition: color var(--transition-fast);
}

.nav__link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--color-accent);
  transition: width var(--transition-base);
}

.nav__link:hover {
  color: var(--color-text-primary);
}

.nav__link:hover::after {
  width: 100%;
}

.nav__link.is-active {
  color: var(--color-accent);
}

.nav__link.is-active::after {
  width: 100%;
}

/* Botón hamburguesa — oculto en desktop */
#nav-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--color-text-primary);
  font-size: var(--font-size-xl);
  padding: var(--space-xs);
  line-height: 1;
  transition: color var(--transition-fast);
}

#nav-toggle:hover {
  color: var(--color-accent);
}

/* ============================================================
   6. SECCIÓN HERO
   ============================================================ */
.section--hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  overflow: hidden;
}

.hero__background {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.hero__overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(10, 10, 10, 0.85) 0%,
    rgba(10, 10, 10, 0.55) 60%,
    rgba(10, 10, 10, 0.75) 100%
  );
}

.hero__content {
  position: relative;
  z-index: 1;
  text-align: center;
  max-width: 800px;
  padding: var(--space-xl) var(--space-md);
}

.hero__eyebrow {
  display: inline-block;
  font-size: var(--font-size-sm);
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: var(--space-sm);
}

.hero__title {
  font-family: var(--font-display);
  font-size: var(--font-size-4xl);
  font-weight: 700;
  line-height: 1.1;
  color: var(--color-text-primary);
  margin-bottom: var(--space-md);
}

.hero__subtitle {
  font-size: var(--font-size-lg);
  color: var(--color-text-secondary);
  max-width: 560px;
  margin: 0 auto var(--space-lg);
  line-height: 1.7;
}

/* ============================================================
   7. BOTONES
   ============================================================ */
.btn {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  font-family: var(--font-body);
  font-size: var(--font-size-sm);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 0.875rem var(--space-lg);
  border-radius: var(--radius-sm);
  border: 2px solid transparent;
  cursor: pointer;
  transition: background-color var(--transition-fast),
              color var(--transition-fast),
              border-color var(--transition-fast),
              transform var(--transition-fast);
}

.btn:active {
  transform: translateY(1px);
}

.btn--primary {
  background-color: var(--color-accent);
  color: var(--color-text-on-accent);
  border-color: var(--color-accent);
}

.btn--primary:hover {
  background-color: var(--color-accent-hover);
  border-color: var(--color-accent-hover);
}

.btn--outline {
  background-color: transparent;
  color: var(--color-accent);
  border-color: var(--color-accent);
}

.btn--outline:hover {
  background-color: var(--color-accent);
  color: var(--color-text-on-accent);
}

.btn--full {
  width: 100%;
  justify-content: center;
}

/* ============================================================
   8. SECCIÓN SERVICIOS
   ============================================================ */
.services__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-md);
}

.service-card {
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-base),
              box-shadow var(--transition-base),
              border-color var(--transition-base);
}

.service-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-card);
  border-color: var(--color-accent);
}

.service-card__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 3rem;
  height: 3rem;
  background-color: rgba(201, 168, 76, 0.12);
  border-radius: var(--radius-sm);
  color: var(--color-accent);
  font-size: var(--font-size-lg);
  margin-bottom: var(--space-sm);
}

.service-card__image {
  width: 100%;
  height: 200px;
  object-fit: cover;
  object-position: center;
}

.service-card__body {
  padding: var(--space-md);
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
}

.service-card__title {
  font-family: var(--font-display);
  font-size: var(--font-size-xl);
  color: var(--color-text-primary);
  line-height: 1.3;
}

.service-card__description {
  font-size: var(--font-size-base);
  color: var(--color-text-secondary);
  line-height: 1.6;
  flex: 1;
}

/* ============================================================
   9. SECCIÓN QUIÉNES SOMOS
   ============================================================ */
.about__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-xl);
  align-items: center;
  margin-bottom: var(--space-2xl);
}

.about__media {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.about__image {
  width: 100%;
  height: 480px;
  object-fit: cover;
  object-position: center;
  display: block;
}

.about__content {
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.about__text {
  font-size: var(--font-size-base);
  color: var(--color-text-secondary);
  line-height: 1.8;
}

.about__stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-sm);
  margin-top: var(--space-sm);
}

.about__stat {
  text-align: center;
  padding: var(--space-sm);
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
}

.about__stat-number {
  font-family: var(--font-display);
  font-size: var(--font-size-2xl);
  font-weight: 700;
  color: var(--color-accent);
  line-height: 1.1;
  display: block;
}

.about__stat-label {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  margin-top: var(--space-xs);
  display: block;
}

/* Equipo */
.team__grid {
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

.team__members {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-md);
}

.team-card {
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  text-align: center;
  transition: transform var(--transition-base),
              box-shadow var(--transition-base);
}

.team-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-card);
}

.team-card__image {
  width: 100%;
  height: 220px;
  object-fit: cover;
  object-position: top center;
}

.team-card__body {
  padding: var(--space-sm) var(--space-md);
}

.team-card__name {
  font-family: var(--font-display);
  font-size: var(--font-size-lg);
  color: var(--color-text-primary);
  margin-bottom: var(--space-xs);
}

.team-card__role {
  font-size: var(--font-size-sm);
  color: var(--color-accent);
  font-weight: 500;
  letter-spacing: 0.04em;
}

/* ============================================================
   10. SECCIÓN CONTACTO
   ============================================================ */
.contact__grid {
  display: grid;
  grid-template-columns: 1fr 1.6fr;
  gap: var(--space-xl);
  align-items: start;
}

.contact__info {
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.contact__info-title {
  font-family: var(--font-display);
  font-size: var(--font-size-2xl);
  color: var(--color-text-primary);
  line-height: 1.2;
}

.contact__info-text {
  font-size: var(--font-size-base);
  color: var(--color-text-secondary);
  line-height: 1.8;
}

.contact__details {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  margin-top: var(--space-xs);
}

.contact__detail-item {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: var(--font-size-base);
  color: var(--color-text-secondary);
}

.contact__detail-item i {
  color: var(--color-accent);
  width: 1.25rem;
  text-align: center;
  flex-shrink: 0;
}

/* Formulario */
.form__group {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
  margin-bottom: var(--space-md);
}

.form__label {
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text-secondary);
  letter-spacing: 0.04em;
}

.form__input,
.form__textarea {
  font-family: var(--font-body);
  font-size: var(--font-size-base);
  color: var(--color-text-primary);
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 0.75rem var(--space-sm);
  width: 100%;
  transition: border-color var(--transition-fast),
              box-shadow var(--transition-fast);
  outline: none;
}

.form__input:focus,
.form__textarea:focus {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(201, 168, 76, 0.15);
}

.form__input.has-error,
.form__textarea.has-error {
  border-color: var(--color-error);
  box-shadow: 0 0 0 3px rgba(224, 82, 82, 0.15);
}

.form__textarea {
  resize: vertical;
  min-height: 140px;
}

.form__error-msg {
  font-size: var(--font-size-sm);
  color: var(--color-error);
  min-height: 1.2em;
}

/* Campo honeypot — visualmente oculto para humanos */
.form__honeypot {
  position: absolute;
  left: -9999px;
  width: 1px;
  height: 1px;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
}

/* Feedback del formulario */
#form-feedback {
  margin-top: var(--space-sm);
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius-sm);
  font-size: var(--font-size-sm);
  font-weight: 500;
  text-align: center;
}

#form-feedback.feedback--success {
  background-color: rgba(82, 160, 82, 0.15);
  border: 1px solid var(--color-success);
  color: var(--color-success);
}

#form-feedback.feedback--error {
  background-color: rgba(224, 82, 82, 0.15);
  border: 1px solid var(--color-error);
  color: var(--color-error);
}

/* ============================================================
   11. FOOTER
   ============================================================ */
#footer-main {
  background-color: var(--color-bg-section);
  border-top: 1px solid var(--color-border);
  padding: var(--space-xl) var(--space-sm) var(--space-lg);
}

.footer__inner {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--space-md);
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

.footer__top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: var(--space-lg);
}

.footer__brand {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
  max-width: 320px;
}

.footer__logo {
  font-family: var(--font-display);
  font-size: var(--font-size-xl);
  font-weight: 700;
  color: var(--color-accent);
}

.footer__tagline {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  line-height: 1.6;
}

.footer__nav {
  display: flex;
  gap: var(--space-xl);
}

.footer__nav-group {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer__nav-title {
  font-size: var(--font-size-sm);
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-text-primary);
}

.footer__nav-link {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  transition: color var(--transition-fast);
}

.footer__nav-link:hover {
  color: var(--color-accent);
}

.footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-md);
  border-top: 1px solid var(--color-border);
  gap: var(--space-sm);
}

.footer__copy {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
}

.footer__social {
  display: flex;
  gap: var(--space-sm);
}

.footer__social-link {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 50%;
  border: 1px solid var(--color-border);
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
  transition: color var(--transition-fast),
              border-color var(--transition-fast),
              background-color var(--transition-fast);
}

.footer__social-link:hover {
  color: var(--color-text-on-accent);
  background-color: var(--color-accent);
  border-color: var(--color-accent);
}

/* ============================================================
   12. ANIMACIONES DE SCROLL
   Usa .is-active como clase de estado autorizada para revelar
   elementos. JS aplica classList.add('is-active') vía
   IntersectionObserver sobre elementos .animate-on-scroll.
   ============================================================ */
.animate-on-scroll {
  opacity: 0;
  transform: translateY(28px);
  transition: opacity var(--transition-base),
              transform var(--transition-base);
}

.animate-on-scroll.is-active {
  opacity: 1;
  transform: translateY(0);
}

/* ============================================================
   13. RESPONSIVE — TABLET (max-width: 1024px)
   ============================================================ */
@media (max-width: 1024px) {
  .services__grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .team__members {
    grid-template-columns: repeat(2, 1fr);
  }

  .about__grid {
    grid-template-columns: 1fr;
    gap: var(--space-lg);
  }

  .about__image {
    height: 360px;
  }

  .about__stats {
    grid-template-columns: repeat(3, 1fr);
  }

  .contact__grid {
    grid-template-columns: 1fr;
    gap: var(--space-lg);
  }

  .hero__title {
    font-size: var(--font-size-3xl);
  }

  .footer__top {
    flex-direction: column;
    gap: var(--space-md);
  }

  .footer__nav {
    gap: var(--space-lg);
  }
}

/* ============================================================
   14. RESPONSIVE — MOBILE (max-width: 768px)
   ============================================================ */
@media (max-width: 768px) {
  /* Header y nav móvil */
  #nav-toggle {
    display: flex;
    align-items: center;
    justify-content: center;
  }

  #nav-main {
    position: fixed;
    top: var(--header-height);
    left: 0;
    width: 100%;
    background-color: rgba(10, 10, 10, 0.98);
    backdrop-filter: blur(8px);
    border-top: 1px solid var(--color-border);
    padding: var(--space-md) 0;
    transform: translateY(-110%);
    transition: transform var(--transition-base);
    z-index: 999;
  }

  #nav-main.is-open {
    transform: translateY(0);
  }

  #nav-menu {
    flex-direction: column;
    gap: 0;
    align-items: stretch;
  }

  .nav__link {
    padding: var(--space-sm) var(--space-md);
    font-size: var(--font-size-base);
    border-bottom: 1px solid var(--color-border);
  }

  .nav__link::after {
    display: none;
  }

  /* Hero */
  .hero__title {
    font-size: var(--font-size-2xl);
  }

  .hero__subtitle {
    font-size: var(--font-size-base);
  }

  /* Secciones */
  .section {
    padding: var(--space-xl) var(--space-xs);
  }

  .section__title {
    font-size: var(--font-size-2xl);
  }

  /* Servicios */
  .services__grid {
    grid-template-columns: 1fr;
  }

  /* About */
  .about__stats {
    grid-template-columns: 1fr;
    gap: var(--space-xs);
  }

  .about__image {
    height: 260px;
  }

  /* Equipo */
  .team__members {
    grid-template-columns: 1fr;
  }

  /* Footer */
  .footer__nav {
    flex-direction: column;
    gap: var(--space-md);
  }

  .footer__bottom {
    flex-direction: column;
    text-align: center;
  }

  /* Botón */
  .btn {
    width: 100%;
    justify-content: center;
  }
}
